  "page.help-button.close": "Close",
  "page.help-button.none.title": "Help",
  "page.help-button.none.body": "Nothing to say here yet.",
  "page.hidden.line.1": "You've gone where the maps don't. A gnome is pretending this was the plan all along.",
  "page.hidden.line.2": "Somewhere under the city, the tram is rattling along. The Index is betting on which end you come out of.",
  "page.hidden.line.3": "The map has lost you. The dwarves say that's normal down here, and they'd know.",
  "page.hidden.line.4": "You're in the deep tunnels now. A goblin is selling guesses at five copper each.",
  "page.hidden.line.5": "The cartographers of Stormwind never drew this bit. They said it was too damp.",
  "page.hidden.line.6": "Off the edge of the map and still moving. The Index is following the rattle of the rails.",
  "page.hidden.line.7": "A secret way under the ground, by the look of it. The Index won't tell anyone.",
  "page.hidden.line.8": "Your dot has gone underground. A gnome engineer insists it's perfectly safe and is holding his breath.",
  "page.hidden.line.9": "Wherever you are, it's dark and it smells of oil. The Index is guessing, and guessing with confidence.",
  "page.hidden.line.10": "You've slipped into one of Azeroth's hidden places. The Index is drawing a line and hoping.",
  "page.items.title": "Items and gear",
  "page.items.key.grind": "Grind for it",
  "page.items.key.gather": "Gather it",
  "page.items.key.quest": "Quest for it",
  "page.items.key.craft": "Craft it",
  "page.items.key.buy": "Buy it",
  "page.items.grind": "This starts a grind loop at the best place for you to farm {name}. The best place is the one that gives you the most {name} an hour, counting the trip there from where you stand.",
  "page.items.gather": "This starts a gathering loop at the best place for you to gather {name}. The best place is the one that gives you the most {name} an hour, counting the trip there from where you stand.",
  "page.items.quest": "This starts a quest epic that ends with {name} as your reward from {quest}. The epic guides you from where you stand to the start of {quest}. If earlier quests lead up to {quest}, the epic takes you through all of them first.",
  "page.items.craft": "This starts a crafting epic for {name}. The epic plans every material you don't have yet, then guides you to craft {name}.",
  "page.items.buy": "This starts the Navigation Guide to {vendor}, the nearest vendor who sells {name}, and copies the line for the in-game arrow.",
  "page.items.grind.none": "There is no place where you can farm {name} at your level.",
  "page.items.quest.none": "No quest you can take now gives {name} as a reward.",
  "page.items.craft.none": "None of your professions can craft {name}, and you have no room to learn one that can.",
  "page.items.buy.none": "No vendor near you sells {name}.",
  "page.items.buy.auction": "This starts the Navigation Guide to {auctioneer}, the nearest auctioneer, since your auction house lists {name}, and copies the line for the in-game arrow.",
  "page.items.up.key": "My Next Upgrades",
  "page.items.up.hover": "This works out the best upgrades for each of your gear slots from quests, vendors, mob drops, dungeons, crafting and the auction house. In each slot, clear upgrades come first, then weak upgrades and then debatable upgrades, and among upgrades of the same kind the ones that are big and easy to get come first.",
  "page.items.up.back": "Back",
  "page.items.up.wait.tailor": "A goblin tailor is measuring you for trousers you haven't earned yet",
  "page.items.up.wait.buckles": "A dwarf quartermaster is counting the buckles on every belt in Azeroth",
  "page.items.up.wait.wands": "An orc grunt is trying the wands to see which one is pointiest",
  "page.items.up.wait.robes": "A gnome is comparing two identical robes with a magnifying glass",
  "page.items.up.wait.cloaks": "The apothecaries are arguing over which cloak smells least",
  "page.items.up.wait.staffs": "A troll is weighing each staff against a slightly better staff",
  "page.items.up.wait.chests": "A tauren is asking every quest giver what's in the reward chest",
  "page.items.up.wait.boots": "A goblin is pricing your future boots by the pound",
  "page.items.up.wait.belts": "A sentinel is sorting the belts by how well they hold up trousers",
  "page.items.up.wait.tables": "A dwarf is reading every loot table twice, in case one lies",
  "page.items.up.empty": "Nothing you can get soon beats what you wear in any slot.",
  "page.items.up.empty.quip": "The quartermaster checked twice and found nothing better than what you wear, and he seemed disappointed",
  "page.items.up.unknown": "The Index works out your upgrades once the game has said what you wear.",
  "page.items.up.failed": "The quartermaster's ledger is shut, so My Next Upgrades didn't go through",
