  "page.layers.on-map": "{layer} is on the map. The {key} key under the zone name starts a loop",
  "page.layers.key.grind": "Grind here",
  "page.layers.key.grind.tip": "Finds the best camp for the character's level in the area in view and a loop round the camp that keeps clear of anything too strong. Zoomed out, the page asks before it searches",
  "page.layers.key.farm": "Farm here",
  "page.layers.key.farm.tip": "Finds the camp worth the most gold an hour for the character's level in the area in view and a loop round the camp that keeps clear of anything too strong. Zoomed out, the page asks before it searches",
  "page.layers.key.skin": "Skin here",
  "page.layers.key.skin.tip": "Finds the best beasts to skin for the character's Skinning in the area in view and a loop round them that keeps clear of anything too strong. The beasts that still raise the skill come first. Zoomed out, the page asks before it searches",
  "page.layers.key.skin.tip.all": "All levels, for planning. Finds the best beasts to skin in the area in view at any level and whatever the skill, each counted as a character of the beast's level would kill it. The beasts that would raise the skill come first, and the loop round them doesn't check for anything too strong. Zoomed out, the page asks before it searches",
  "page.layers.key.skin.leathers": "{tip}. The loop goes only to the beasts that give {leathers}",
  "page.layers.key.gather": "Gather here",
  "page.layers.key.gather.tip": "Makes a loop through where the resources shown here that the character can gather are thickest in the area in view, with one stop in the middle of each cluster. While the character can gather none of them yet, the loop goes through all the resources shown here",
  "page.layers.key.loop": "loop",
  "page.layers.key.loop.tip": "Makes a loop through where {name} grows or spawns thickest in the area in view, with one stop in the middle of each cluster",
  "page.layers.aoe": "AOE",
  "page.layers.aoe.tip": "AOE finds the camp with the densest packs of mobs at the character's level or below, for pulls of several at once. Casters and shooters count against a camp",
  "page.layers.ah": "Include AH prices",
  "page.layers.ah.tip": "Counts gold an hour with the loot at what it sells for in the auction house. The page uses what an item sold for lately where the scans saw it. Without a sale the page uses the middle price the item is listed at, and without a listing what a vendor pays. Gear that drops with a random suffix counts at the average of its suffixes' prices, each weighed by how often that suffix is listed. With Skinning, the skins of the beasts the character can skin count too",
  "page.layers.daredevil": "Daredevil",
  "page.layers.daredevil.tip": "With Daredevil on, the loop avoids no mob. The loop keeps every spawn point and its legs go straight through, whatever stands near. With Daredevil off, the loop avoids every mob that would attack except the ones grey to the character. The loop then leaves out the points in a mob's reach and goes round the mob",
  "page.layers.aoe.warn": "You are not an AOE spec. {list} are AOE specs. The page counts the packs for {n} mobs a pull",
