  "page.level-report.missing-title.stats": "Your new stats",
  "page.level-report.missing.played.1": "A dwarf of the Explorers' League started counting your hours at this level, then found a dig site and forgot.",
  "page.level-report.missing.played.2": "The bronze dragons keep the hours of every level, and they aren't telling anyone how long this one took.",
  "page.level-report.missing.played.3": "Two Tauren elders argued over how long this level took you. They agreed that it was a while.",
  "page.level-report.missing.played.4": "The goblin who sells hourglasses in Booty Bay wants a deposit before he says how long you spent here.",
  "page.level-report.missing.played.5": "Brann Bronzebeard wrote down how long you spent at this level, and then he lost the notebook.",
  "page.level-report.missing.played.6": "A night elf sentinel kept time for this level, but she counts in moons and she is still waiting for one.",
  "page.level-report.missing.gold.1": "A Venture Company accountant took your ledger for this level and has not come back.",
  "page.level-report.missing.gold.2": "The bankers of Ironforge were closed for a holiday that nobody else has heard of.",
  "page.level-report.missing.gold.3": "The goblins of Gadgetzan counted your gold for this level and kept the total as their fee.",
  "page.level-report.missing.gold.4": "A Defias bookkeeper had your gold count for this level. Nobody has seen him since the Deadmines.",
  "page.level-report.missing.gold.5": "A kobold was put in charge of your gold count. He only wanted the candle.",
  "page.level-report.missing.gold.6": "The Steamwheedle Cartel will tell you what you made at this level, for a small consideration.",
  "page.level-report.missing.gold-hour.1": "The goblins of the Gadgetzan auction house tried to count your gold per hour and are still arguing about the decimal.",
  "page.level-report.missing.gold-hour.2": "A gnome in Tinker Town is building a machine to work out your gold per hour. He has been building it for some time.",
  "page.level-report.missing.gold-hour.3": "The apothecaries of the Undercity were asked for your gold per hour. They sent back a vial, which helped nobody.",
  "page.level-report.missing.gold-hour.4": "A Booty Bay pirate offered to work out your gold per hour, but he only counts in doubloons.",
  "page.level-report.missing.gold-hour.5": "An ogre in Dire Maul was given your gold per hour to count. He got as far as two.",
  "page.level-report.missing.gold-hour.6": "The dwarves of the Ironforge mint weighed your gold, but nobody gave them the hours to weigh it against.",
  "page.level-report.missing.pace.1": "A gnome engineer was timing your level with a stopwatch. The stopwatch exploded.",
  "page.level-report.missing.pace.2": "The night elves measured your pace in centuries and found this level too short to write down.",
  "page.level-report.missing.pace.3": "A Darkspear troll watched you level and says you were quick. He gave no number.",
  "page.level-report.missing.pace.4": "The Kirin Tor have a spell for your levelling speed, and the apprentice who knew it is a sheep this week.",
  "page.level-report.missing.pace.5": "A goblin bookmaker took bets on how fast you would level and left town before paying out.",
  "page.level-report.missing.pace.6": "A kodo herder from Mulgore timed your level against his slowest kodo. The kodo has not finished yet.",
  "page.level-report.missing.kills.1": "The Argent Dawn sent a clerk to count your kills at this level. He is still counting the boars.",
  "page.level-report.missing.kills.2": "A murloc kept the count of your kills at this level. Nobody can read what he wrote.",
  "page.level-report.missing.kills.3": "The Scourge claim some of your kills as their own and are disputing the count.",
  "page.level-report.missing.kills.4": "A Forsaken apothecary says your kills will be counted once they stop getting back up.",
  "page.level-report.missing.kills.5": "The spirit healers keep a list of everyone you sent their way, and they don't share it.",
  "page.level-report.missing.kills.6": "A Kodo herder offered to tally your kills, but he only counts in kodos.",
  "page.level-report.missing.spell.1": "The Kirin Tor asked all over Dalaran about your favourite spell. Nobody would say.",
  "page.level-report.missing.spell.2": "A gnome counted every spell you cast at this level and then turned himself into a sheep by mistake.",
  "page.level-report.missing.spell.3": "Your class trainer has a guess at your favourite spell and keeps it to themselves.",
  "page.level-report.missing.spell.4": "The Shen'dralar keep a book of everyone's favourite spells, and the page with yours is missing.",
  "page.level-report.missing.spell.5": "A murloc watched every spell you cast at this level and liked all of them the same.",
  "page.level-report.missing.spell.6": "The shamans of the Earthen Ring asked the elementals about your favourite spell and got four different answers.",
  "page.level-report.missing.stats.1": "A dwarf of Ironforge measured your new strength with a hammer and wrote nothing down.",
  "page.level-report.missing.stats.2": "The druids of the Cenarion Circle say you grew this level, but they measure growth in tree rings.",
  "page.level-report.missing.stats.3": "A goblin offered to weigh your new stats on his scales, for a fee that he hasn't named yet.",
  "page.level-report.missing.stats.4": "The scribes of Stormwind write down a level's new stats when you next log out or reload, and not a moment before.",
  "page.level-report.missing.stats.5": "An Orgrimmar grunt sized you up after this level and said you look about the same.",
  "page.level-report.missing.stats.6": "The gnomes built a machine to read your new stats. The machine is in Gnomeregan, which is a problem.",
  "page.level-report.missing.when.1": "You reached level {level}{where} at some point in the last few days. The goblin keeping the calendar was paid by the hour and saw no reason to rush.",
  "page.level-report.missing.when.2": "You reached level {level}{where}, sometime. A gnome had a clock on it, and the clock is now a small fire.",
  "page.level-report.missing.when.3": "You reached level {level}{where} while nobody was looking. The bronze dragons know when, and they're not saying.",
  "page.level-report.missing.when.4": "You reached level {level}{where} on a day the scribes of Stormwind took off. They have written it down as 'recently'.",
  "page.level-report.missing.when.5": "You reached level {level}{where}. A Tauren elder says it was a few moons ago. A night elf says it was a moment ago. Both are sure.",
  "page.level-report.missing.when.6": "You reached level {level}{where} at an hour the Undercity's clocks don't keep, since nobody there needs to know when lunch is.",
