  "page.reagents.doing.1": "Reading the recipe twice, because the first time it seemed to ask for a whole murloc",
  "page.reagents.doing.2": "Working out what the recipe takes, as the trainer's handwriting leaves a lot to the imagination",
  "page.reagents.doing.3": "Listing what the recipe takes, so nobody reaches the anvil and starts patting their pockets",
  "page.reagents.doing.4": "Asking a gnome what goes into it, as gnomes answer every question with a diagram",
  "page.reagents.cloth.1": "Measuring out the {item}, as the tailors of Stormwind measure twice and charge three times",
  "page.reagents.cloth.2": "Counting the {item}, because the humanoids drop it generously once persuaded",
  "page.reagents.cloth.3": "Holding the {item} up to the light, as a moth got to the last lot first",
  "page.reagents.leather.1": "Counting the {item} you need, as the boars of Azeroth are not offering it up",
  "page.reagents.leather.2": "Checking the {item} for holes, because its last owner was still wearing it",
  "page.reagents.leather.3": "Weighing up the {item}, as leatherworking is mostly patience and a strong stomach",
  "page.reagents.metal.1": "Weighing the {item}, as a dwarf will check the sums with a hammer",
  "page.reagents.metal.2": "Counting out the {item}, because every bit of it was once a rock a miner hit all afternoon",
  "page.reagents.metal.3": "Asking after the {item}, so a dwarf in Ironforge can say it was better in his day",
  "page.reagents.herb.1": "Looking for {item}, as it grows exactly where the crocolisks like to nap",
  "page.reagents.herb.2": "Counting the {item} you need, because a druid is watching and taking notes",
  "page.reagents.herb.3": "Checking the {item} is the right herb, as the apprentice's last bunch turned out to be lettuce",
  "page.reagents.meat.1": "Finding the {item}, as the cook wants it fresh and its owner had other plans",
  "page.reagents.meat.2": "Adding the {item} to the shopping list, so the cook can stop glaring at the pantry",
  "page.reagents.meat.3": "Sniffing the {item} with care, because a cook in Westfall once skipped that step",
  "page.reagents.parts.1": "Counting the {item}, as a gnome engineer swears it won't explode this time",
  "page.reagents.parts.2": "Sorting the {item} from the spare parts, because there are always spare parts afterwards",
  "page.reagents.parts.3": "Polishing the {item}, so the goblin who sold you the schematic can't blame the parts",
  "page.reagents.elemental.1": "Asking a shaman about the {item}, as the elements drive a hard bargain",
  "page.reagents.elemental.2": "Wrapping the {item} in something fireproof, because the last apprentice didn't",
  "page.reagents.elemental.3": "Pricing the {item}, as elementals are never cheap and never grateful",
  "page.reagents.enchanting.1": "Sweeping up the {item}, as enchanters keep disenchanting perfectly good boots",
  "page.reagents.enchanting.2": "Measuring the {item} by the pinch, because a heap of it once turned a gnome blue",
  "page.reagents.enchanting.3": "Counting the {item}, so nobody sneezes on it this time",
  "page.reagents.goods.1": "Fetching the {item}, as no recipe in Azeroth is complete without one more little jar of something",
  "page.reagents.goods.2": "Adding the {item} to the list, because it's always the small thing that sends you back across town",
  "page.reagents.goods.3": "Checking the {item} against the recipe, as the apprentice once used the spices for dye",
  "page.reagents.reagent.1": "Finding the {item}, because recipes in Azeroth ask for odd things and nobody argues with a recipe",
  "page.reagents.reagent.2": "Fitting the {item} into the plan, as whoever wrote the recipe had a sense of humour",
  "page.reagents.vendor.1": "Sending you to {npc} for {item}, as trade suppliers keep it in a drawer and nobody knows why",
  "page.reagents.vendor.2": "Finding a vendor who stocks {item}, so you can skip the part where you fight something for it",
  "page.reagents.vendor.3": "Putting {item} on the shopping list for {npc}, because buying it beats making it and swearing",
  "page.reagents.auction.1": "Bidding on {item} at the auction house, as the goblins there price it with great imagination",
  "page.reagents.auction.2": "Buying {item} at the auction house, because somebody else did the farming and wants paying for it",
  "page.reagents.auction.3": "Sending a runner to the auctioneer for {item}, so the goblins get their cut and you keep your afternoon",
  "page.reagents.weigh.1": "Weighing the auction house's price for {item}, as the goblin behind the counter swears it's a bargain",
  "page.reagents.weigh.2": "Picking the cheapest way to your {item}, because a copper saved is a copper no goblin gets",
  "page.reagents.weigh.3": "Comparing prices on {item}, as the auction house and the vendors have never once agreed",
  "page.reagents.bags.1": "Rummaging through your bags for {item}, as adventurers keep everything just in case",
  "page.reagents.bags.2": "Counting the {item} already in your bags, so no goblin sells you what you own",
  "page.reagents.bags.3": "Finding {item} in your bags under a pile of grey loot, as is traditional",
  "page.reagents.bank.1": "Asking the bank about your {item}, as the banker remembers everything and admits nothing",
  "page.reagents.bank.2": "Checking the bank for {item}, because you put some there once and forgot",
  "page.reagents.bank.3": "Writing to the bank about the {item}, so the gnome at the counter has something to read",
  "page.realign.title": "Re-aligning",
  "page.realign.wait.1": "The Kirin Tor are re-aligning the ley lines",
  "page.realign.wait.2": "The cartographers of Stormwind are redrawing their charts",
  "page.realign.wait.3": "A dwarf is holding the old maps up to the new ones and squinting",
  "page.realign.wait.4": "The surveyors are pacing the roads again and grumbling about it",
  "page.realign.wait.5": "The scribes are copying out the new pages by hand",
  "page.realign.wait.6": "A gnome engineer is recalibrating the gears with a large wrench",
  "page.realign.wait.7": "The Explorers' League is checking its notes against the new dig",
  "page.realign.wait.8": "Two loremasters are comparing the old tomes with the new. They have agreed on nothing yet",
  "page.realign.wait.9": "A Kirin Tor apprentice is tuning the arcane compass. A rat nearby is now purple",
  "page.realign.wait.10": "The keepers of Uldaman are putting their vaults in order",
