  "page.counting.market.col.profit": "Profit per craft",
  "page.counting.market.col.profit.tip": "Profit is what one craft of this item earns. The Index takes the market price of the item times the number one craft makes and takes the auction house's cut off that. The Index then takes what the craft's reagents cost at the market price off the rest. If you pay more than the market price for a reagent, the craft can lose money.",
  "page.counting.market.col.margin": "Margin",
  "page.counting.market.col.margin.tip": "Margin is the profit of one craft as a share of what the craft's reagents cost at the market price. The auction house's cut is already off the item's value. If you pay more than the market price for a reagent, the craft can lose money.",
  "page.counting.market.col.goldday": "Gold a day",
  "page.counting.market.col.goldday.tip": "The gold a day one craft of this item is worth at the market's sales rate: the profit of one craft times the units that sell a day at the market's sales rate, over the units one craft makes. A craft whose product sells rarely earns little even at a large profit.",
  "page.counting.market.cell.goldday.top": "{coins} a day at the market's sales rate.",
  "page.counting.market.cell.goldday.work": "The profit of one craft, {profit}, times {n} crafts' worth sold a day at the market's rate.",
  "page.counting.market.cell.goldday.rare": "A craft whose product sells rarely earns little even at a large profit.",
  "page.counting.market.cell.goldday.rate": "One craft's worth of this item or more sells a day, so the gold a day is at least the profit of one craft.",
  "page.counting.market.cell.goldday.profit": "Less than one craft's worth of this item sells a day, so the gold a day is a share of the profit of one craft.",
  "page.counting.market.cell.goldday.none": "No sales rate",
  "page.counting.market.cell.goldday.none.tip": "The market has no sales rate for this item, so the gold a day of one craft is left out of this order.",
  "page.counting.market.col.change": "Change",
  "page.counting.market.col.change.tip": "The market price now against the average of the last 30 days.",
