  "page.counting.market.col.sold": "Sold per day",
  "page.counting.market.col.sold.tip": "The units sold per day, as two full scans a day apart would judge them. The figure is an estimate from your scans. The 90% range is measured on the past scans of this auction house.",
  "page.counting.market.col.supply": "Days to sell the lowest-priced stock",
  "page.counting.market.col.supply.tip": "How many days the units at the lowest price would last at the estimated sales per day.",
