  "page.counting.market.col.age": "Last scan",
  "page.counting.market.col.confidence": "Confidence",
  "page.counting.market.col.confidence.tip": "How far the market price can be trusted, rated by the width of the 90% range. The rating is High when the range is under half the price, Medium up to one and a half times the price and Low above that. High shows only where ranges of that width and that gap between scans were measured on the past scans of this auction house.",
  "page.counting.market.cell.listed.tip": "{n} on average over the last 30 days",
