  "page.counting.market.cell.sold.prior": "Category median",
  "page.counting.market.cell.sold.prior.tip": "No two full scans in a row listed this item yet, so this figure is the median sales per day of items of the same type, with a wide range.",
  "page.counting.market.cell.sold.none": "No pair of scans yet",
  "page.counting.market.cell.sold.none.tip": "There are not enough pairs of scans yet for sales per day. Two full scans of this auction house start this figure, however far apart the two scans are.",
