  "page.counting.market.cell.unlisted": "Not listed now",
  "page.counting.market.cell.unlisted.tip": "The last scan had no auction of this item.",
  "page.counting.market.table.more": "The {n} items with the most gold sold per day show here. Click a tile in the diagram to see every item of a category.",
  "page.counting.market.table.more.profit": "The {n} crafts worth the most gold a day show here. Click a tile in the diagram to see every item of a category.",
  "page.counting.market.profit.order": "Order by profit",
  "page.counting.market.profit.order.tip": "Orders the table by the gold a day one craft of each item is worth: the profit of one craft times how many crafts' worth sell a day at the market's sales rate. The crafts worth the most come first and the items no recipe makes come last. Press Order by profit again to put the table back in its usual order.",
  "page.counting.market.profit.left": "{n} recipes have no market price for their item or their reagents, so the profit of one craft is left out of this table.",
  "page.counting.market.profit.left.one": "1 recipe has no market price for its item or its reagents, so the profit of one craft is left out of this table.",
  "page.counting.market.profit.left.sales": "{n} items with a recipe have no sales rate on this auction house, so the gold a day of one craft is left out of this order.",
  "page.counting.market.profit.left.sales.one": "1 item with a recipe has no sales rate on this auction house, so the gold a day of one craft is left out of this order.",
  "page.counting.market.flag.pooled": "All suffixes",
  "page.counting.market.flag.pooled.tip": "These figures come from scans made before the Index read random suffixes, so the figures pool every suffix of this item. The figures are not the price of any one suffix.",
  "page.counting.market.flag.vendor": "Below vendor price",
  "page.counting.market.flag.vendor.tip": "An auction of this item costs less than the vendor price.",
  "page.counting.market.flag.bait": "Possible bait",
  "page.counting.market.flag.bait.tip": "The lowest buyout is far below every other auction of this item. The auction may be a trap for buyers in a hurry, so the market price leaves the auction out.",
  "page.counting.market.flag.reset": "Possible reset",
  "page.counting.market.flag.reset.tip": "The cheapest auctions of the scan before are all gone and the price jumped. A player may have bought out the cheap auctions to post them higher. The units sold in the possible reset are left out of the sales per day.",
