  "page.counting.odds.states": "Market states at the next scan",
  "page.counting.odds.states.tip": "A market state describes the price now against the 30 day average. Here each market state is checked against the next scan of the same item, for all items in that state, then separately for items shown as sure and items marked uncertain.",
  "page.counting.odds.state.sure": "{state} (sure)",
