  "page.counting.odds.col.side": "Same side of the 30 day average",
  "page.counting.odds.picks": "Recommendations replayed on past scans",
  "page.counting.odds.picks.tip": "At every past scan, the Index worked out the chance that one auction posted at the lowest buyout would sell, the same way the recommendations work it out. Where that scan is still kept whole, it also worked out each Buy recommendation as made then: the auctions bought and their relist at its price. Each chance was then checked against what the later scans judged sold at the listing's price or dearer. A check counts only where no two full scans during the listing were more than {edge} apart, which is the gap the sales pace is measured at. Listings under 1.05 times the lowest buyout are shown here. Dearer relists are checked apart, so a chance checked at the lowest buyout never rates them. In a band of the chance where the model's chance was off, or where the share sold on earlier scans came closer to what sold, the band shows that share. Every other band shows the model's chance. No band shows a higher chance than a band of a higher chance shows.",
  "page.counting.odds.picks.tip.any": "At every past scan, the Index worked out the chance that one auction posted at the lowest buyout would sell, the same way the recommendations work it out. Where that scan is still kept whole, it also worked out each Buy recommendation as made then: the auctions bought and their relist at its price. Each chance was then checked against what the later scans judged sold at the listing's price or dearer. Listings under 1.05 times the lowest buyout are shown here. Dearer relists are checked apart, so a chance checked at the lowest buyout never rates them. In a band of the chance where the model's chance was off, or where the share sold on earlier scans came closer to what sold, the band shows that share. Every other band shows the model's chance. No band shows a higher chance than a band of a higher chance shows.",
  "page.counting.odds.picks.range": "{low} to {high} times the lowest buyout",
  "page.counting.odds.picks.range.top": "{low} times the lowest buyout and more",
  "page.counting.odds.picks.level": "Relists at {span} are checked apart: {n} checked, {came} sold.",
  "page.counting.odds.picks.level.thin": "Relists at {span} are not checked yet: {n} settled of the 50 needed, so the recommendations show the model's chance for them. Buy recommendations are replayed only on the last 40 scans, which the Index keeps whole.",
  "page.counting.odds.picks.flips": "Buy recommendations replayed whole: {n} settled, {gained} made gold, {lost} lost gold, {net} in all.",
  "page.counting.odds.picks.use": "For selling before the last listing ends, {sells} of {sellsof} bands of the chance show the share that sold on past scans, and {sellscapped} bands show the model's chance capped at the band above. For selling within one listing, {one} of {oneof} bands show the share that sold, and {onecapped} bands show the model's chance capped at the band above. The other bands show the model's chance.",
  "page.counting.odds.picks.key": "Each dot is a group of replayed listings. Across is the chance, and up is the share that sold.",
  "page.counting.odds.picks.set.sells.before": "Sold before the last listing ended, the model's chance",
  "page.counting.odds.picks.set.sells.after": "Sold before the last listing ended, the corrected chance",
  "page.counting.odds.picks.set.sells.shown": "Sold before the last listing ended, the chance the recommendations show",
  "page.counting.odds.picks.set.one.before": "Sold within one listing, the model's chance",
  "page.counting.odds.picks.set.one.after": "Sold within one listing, the corrected chance",
  "page.counting.odds.picks.set.one.shown": "Sold within one listing, the chance the recommendations show",
  "page.counting.odds.picks.n.tip": "Listings replayed and checked against the scans after them, each only where no two full scans during the listing were more than {edge} apart. A corrected chance counts only once the earlier scans settled enough listings to correct the chance.",
  "page.counting.odds.picks.n.tip.any": "Listings replayed and checked against the scans after them. A corrected chance counts only once the earlier scans settled enough listings to correct the chance.",
  "page.counting.odds.col.predicted": "Chance shown",
  "page.counting.odds.picks.verdict.holds": "Sold as often as shown",
  "page.counting.odds.picks.verdict.holds.tip": "The listings sold about as often as the chance shown.",
  "page.counting.odds.picks.verdict.low": "Sold less often than shown",
  "page.counting.odds.picks.verdict.low.tip": "The listings sold less often than the chance shown, by more than chance explains. Read the chance to sell in the recommendations as too high.",
  "page.counting.odds.picks.verdict.high": "Sold more often than shown",
  "page.counting.odds.picks.verdict.high.tip": "The listings sold more often than the chance shown, by more than chance explains. Read the chance to sell in the recommendations as too low.",
