  "page.counting.odds.picks.verdict.thin.tip": "There are fewer than 50 checks, which is too few to say whether the chance holds.",
  "page.counting.odds.record": "Your finished auctions",
  "page.counting.odds.record.thin": "{n} of your auctions have finished and been scored against the chance the Index gave them. The chart of your finished auctions needs {needs}.",
  "page.counting.odds.record.how": "A finished auction counts once the game confirms that the auction sold or expired. Each finished auction is given the chance the Index would have shown from the scans before you posted it. A cancelled auction is left out, because the auction ended before the time ran out.",
  "page.counting.odds.record.thin.flavour": "The bookkeeper will not draw a curve through no points at all. He has seen it done, and it ended badly.",
