  "page.counting.picks.checks.apart": "The Index cannot check yet how often listings like these recommendations sold. During every past listing, your full scans of this auction house were {gap} or more apart at least once. Do a full scan at least every {edge} for {span}, and the check starts.",
  "page.counting.picks.hold.guide": "The figures of each recommendation cover {listings} listings of {span} each, the longest duration WoW Forever guides give. Goods still unsold after the last listing are sold to a vendor.",
