  "page.counting.picks.effects": "Fees, listings and market effects",
  "page.counting.picks.effects.patch": "A patch or hotfix that changed an item widens the price range of that item. The Index measured how much on the past scans of this auction house.",
  "page.counting.picks.effects.state": "The figures use the market state of each item. A price above or below the usual level of the item is expected to move back toward that level as fast as prices in the same market state did on the past scans of this auction house. A listing is expected to meet as many undercuts as listings in the same market state met on those scans.",
  "page.counting.picks.effects.launch": "The time since WoW Forever launched is left out of the figures. Measured on the scans, the time since launch made the forecasts worse.",
  "page.counting.picks.effects.week": "The weekday and the hour of day are not measured yet, so every recommendation's confidence is one step lower. Measuring the weekday and the hour takes weeks of scans at many hours of the day.",
  "page.counting.picks.effects.opening.raid": "Raids open on {day}. The Index has not measured yet how raid openings move prices, and the confidence of every recommendation already counts openings as not measured.",
