  "page.counting.sales.fact": "{n} ({low} to {high})",
  "page.counting.sales.fact.tip": "The units of this item sold per day, as two full scans a day apart would judge them. The figure is an estimate from every pair of full scans in a row. The range is the 90% range of what such a day shows. On the past scans of this auction house, ranges set this way held 9 times in 10. An auction that is gone between two scans may have sold, expired or been cancelled, so each gone auction is weighted. Units come in whole auctions, so the range counts in auctions of the usual size for this item.",
  "page.counting.sales.fact.prior": "Category median",
  "page.counting.sales.fact.prior.tip": "No two full scans in a row listed this item yet, so this figure is the median sales per day of items of the same type, with a wide range.",
