  "page.gear.upgrades.title": "Next upgrades",
  "page.gear.upgrades.about.dungeon": "This list shows the best upgrades for each slot from the dungeons. Clear upgrades come first, then weak upgrades and then debatable upgrades, and among upgrades of the same kind the ones that are big and easy to get come first. When nothing within your reach upgrades a slot, the list shows the piece from the next dungeon up. A piece out of reach for now is greyed out, and a red skull beside the piece says the level it needs.",
  "page.gear.upgrades.about.raid": "This list shows the best upgrades for each slot from the raids. Clear upgrades come first, then weak upgrades and then debatable upgrades, and among upgrades of the same kind the ones that are big and easy to get come first. When nothing within your reach upgrades a slot, the list shows the piece from the next raid up. A piece out of reach for now is greyed out, and a red skull beside the piece says the level it needs.",
  "page.gear.upgrades.asked.weights": "the stat weights",
